preConditionHook:
// EL: Highest(h, lookback)[1] is the previous bar's Highest -- the N bars
// ending one bar ago, i.e. today's high[1..lookback]. Highest bottoms out in
// Extremes(), EL SOURCE: seeded at the first bar of its window, scanning the
// rest with a strict, tolerance-carrying comparison (see Breakout), so this
// seeds at high[1] and scans high[2..lookback] with el_gt/el_lt.
priorHighestHigh = high[1];
priorLowestLow = low[1];
for (int i = 2; i <= (int)lookback; ++i) {
    if (el_gt(high[i], priorHighestHigh)) priorHighestHigh = high[i];
    if (el_lt(low[i], priorLowestLow)) priorLowestLow = low[i];
}
